import{_ as a,o,c as i,a3 as t}from"./chunks/framework.B7pF4b99.js";const u=JSON.parse('{"title":"Spec 32：WUFS0002 整磁區 redo journal 與安全儲存","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-32-wufs-redo-journal.md","filePath":"SPEC-32-wufs-redo-journal.md","lastUpdated":1794203475000}'),s={name:"SPEC-32-wufs-redo-journal.md"};function d(r,e,l,c,n,h){return o(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="spec-32-wufs0002-整磁區-redo-journal-與安全儲存" tabindex="-1">Spec 32：WUFS0002 整磁區 redo journal 與安全儲存 <a class="header-anchor" href="#spec-32-wufs0002-整磁區-redo-journal-與安全儲存" aria-label="Permalink to &quot;Spec 32：WUFS0002 整磁區 redo journal 與安全儲存&quot;">​</a></h1><p>日期：2026-11-06。</p><p>狀態：WUFS0002、redo/recovery、舊版唯讀、主機映像安全更新已實作；scratch QEMU 已驗證正常寫入、錯誤回復、滿盤保護與 fan 儲存。未宣稱實體斷電或所有 VirtIO 硬體的 flush 語意均已驗證。</p><h2 id="目標與範圍" tabindex="-1">目標與範圍 <a class="header-anchor" href="#目標與範圍" aria-label="Permalink to &quot;目標與範圍&quot;">​</a></h2><p>公開檔案系統修改操作必須在寫回正式磁區前完成一筆有界交易。遇到錯誤或容量不足時，尚未提交的修改只存在 RAM，不得將原檔或 metadata 部分改壞。已提交但尚未完整 checkpoint 的交易，重新開機時要重做完整紀錄。包含 <code>mkdir</code>、<code>touch</code>、<code>remove</code>、<code>remove_tree</code>、<code>copy</code>、整檔 <code>write</code>、truncate 與 FD inode write。</p><p>教科書中的 journaling／redo 與 recovery 概念參照使用者筆記 <code>notes/chapter 14 File-System Implementation.md</code> §14.7；區塊裝置請求及 DMA/I/O 分層參照 <code>notes/ch12 I_O Systems.md</code>。這裡是 WUWAOS 的整磁區 redo 設計，不是 ext3 或 POSIX VFS。</p><h2 id="磁碟相容與布局" tabindex="-1">磁碟相容與布局 <a class="header-anchor" href="#磁碟相容與布局" aria-label="Permalink to &quot;磁碟相容與布局&quot;">​</a></h2><ul><li><code>WUFS0001</code> 不做原地轉換，kernel 僅在嚴格 layout／metadata 驗證通過後唯讀掛載；所有修改回 <code>-30</code>（read-only）。host <code>make_disk.py</code> 對 V1 不更新映像；指定 <code>--install</code> 時拒絕，建立新檔案系統需指定新的 <code>DISK_IMAGE</code>。</li><li>全零新磁碟由 kernel 或 host 工具建立 <code>WUFS0002</code>。不支援未知非空白映像自動格式化。</li><li>16 MiB 映像固定配置如下；所有 LBA 單位均為 512 bytes。</li></ul><table tabindex="0"><thead><tr><th>LBA</th><th>內容</th></tr></thead><tbody><tr><td>0</td><td>Superblock；沿用前 9 個 WUFS 幾何欄位，word 11–13 記錄 journal 起點、長度及容量</td></tr><tr><td>1</td><td>Journal header，含 <code>WUJNL002</code>、版本、sector 數、commit state 及 CRC32</td></tr><tr><td>2–10</td><td>9-sector 目標 LBA 表，可列 1152 個 sector</td></tr><tr><td>11–1162</td><td>1152 個完整 512-byte redo sector image</td></tr><tr><td>1163</td><td>Inode bitmap</td></tr><tr><td>1164–1171</td><td>Block bitmap</td></tr><tr><td>1172–1191</td><td>128 個、每個 80-byte 的 inode</td></tr><tr><td>1192 之後</td><td>Data 區</td></tr></tbody></table><p>Journal extent 總長 1162 sectors；其 sectors 在 block bitmap 中永久標為已用。Superblock layout 必須精確吻合該格式，超過 32768 sectors 的裝置拒絕掛載。Header 全零表示沒有 pending transaction；任何非零但無效的 header 都拒絕掛載，不猜測、不清除。有效紀錄需在 replay 前驗完 header state/reserved bytes、CRC、count、目標範圍、重複 LBA 及完整 payload；目標不得落在 superblock 或 journal。</p><h2 id="commit、錯誤與-recovery" tabindex="-1">Commit、錯誤與 recovery <a class="header-anchor" href="#commit、錯誤與-recovery" aria-label="Permalink to &quot;Commit、錯誤與 recovery&quot;">​</a></h2><p>一筆 transaction 將每個唯一目標 sector 暫存在 589,824-byte RAM buffer（另有 4.5 KiB LBA index），讀取會先查 staged copy。配置快取需連續 144 個 4 KiB 頁；失敗時不掛載新格式磁碟或拒絕 V2 掛載。最多 1152 個不同 sector；超過即回 <code>-28</code>，整筆 abort，正式區尚未寫入。</p><p>Commit 順序為：寫完整目標表與 redo payload → VirtIO FLUSH → 寫已提交 header → FLUSH → 將每個 redo sector 寫回 home LBA → FLUSH → 清零 header → FLUSH。FLUSH feature 未協商到時，乾淨的 V2 volume 只唯讀掛載；若 header pending，拒絕掛載而不嘗試不耐久的 replay。VirtIO block flush request 依 VirtIO 1.2 block FLUSH request 格式，sector 欄位設為 0。</p><p>此實作假設單 hart 核心交易期間不與另一個核心並行修改 WUFS，也不允許 host 工具在 QEMU 使用映像時同時改寫它。FLUSH 提供裝置所宣告的持久化屏障；若裝置回報寫入完成但未遵守該契約，軟體無法保證媒體持久性。Checksum 用來拒絕損毀紀錄，不是資料救援機制；任何 torn／損毀後的非零 header 都保留並拒絕掛載，不自動修復。</p><p>整檔 payload 也在 redo buffer 中，因此同一 transaction 可以在 staged bitmap 釋放舊 blocks 後再配置新 blocks；正式磁碟直到 commit 前仍保有完整舊版本。這讓 <code>fs_write</code>／<code>fan</code> 的單次整檔 SYS_FS_WRITE 原子發佈，不必同時保留舊檔和新檔的全部空間。Copy、刪除樹等操作超過 journal sector 上限時整筆拒絕，不分批留下半套樹。</p><p>Commit header 成功持久化後，即使後續 home write 回錯，呼叫者仍可能收到 <code>-5</code>，而重啟後 redo 會使操作生效；這是結果不確定狀態，使用者不應盲目重試。任何交易 I/O 失敗會將該次開機的 volume 標為 offline；重新啟動後由有效 committed log 決定 replay。區塊請求逾時仍沿用既有 fail-stop 行為，不會返回 syscall 錯誤；需要重啟後再復原。</p><p>FD 的每次 <code>io_write</code> 最多提交 512 bytes 為一個 transaction；多次 FD write 不合併成整檔 transaction。<code>O_TRUNC</code> 與後續 write 是分開的交易，因此 shell <code>&gt; file</code> 在 open/truncate 成功後，後續寫入失敗不會還原舊內容。資料寫入可按 FD 呼叫粒度失敗；metadata 不得假裝成功。</p><h2 id="驗證及-host-formatter" tabindex="-1">驗證及 host formatter <a class="header-anchor" href="#驗證及-host-formatter" aria-label="Permalink to &quot;驗證及 host formatter&quot;">​</a></h2><p>Kernel 掛載前驗證 superblock 範圍與精確布局；replay 後掃描 inode/block bitmaps、inode 類型與大小、必要 data pointers、indirect pointers 範圍/重複/bitmap 所有權、directory entry 名稱和 inode 編號、root <code>.</code>／<code>..</code>、目錄可達性與父項。Data 區 bitmap 必須與 inode pointer ownership 相符。這是 WUFS 的一致性檢查，不包含資料內容 checksum，也不會自動修復壞格式。</p><p><code>tools/make_disk.py</code> 只直接更新無 pending journal 且通過同等 WUFS0002 metadata 驗證的映像；任何非零 journal header（有效或損毀）都拒絕。工具在記憶體完成修改後，寫同目錄暫存檔、flush/fsync，再用 replace 取代目標；POSIX 也 fsync parent directory。Windows 對目錄項目持久性的保證受 OS／檔案系統限制。Pending journal 必須先由 kernel 開機復原後，再以正確流程處理映像；host 工具不做 replay。</p><p><code>build/kernel.elf</code> 是 QEMU 實際啟動的 debug kernel。<code>build/kernel-disk.elf</code> 只是普通檔案系統副本；因 kernel ELF 超過每檔案 528384-byte 限制，該副本用 <code>llvm-objcopy --strip-all</code> 壓小，啟動方式不變。</p><h3 id="新磁碟與-pending-recovery-操作" tabindex="-1">新磁碟與 pending recovery 操作 <a class="header-anchor" href="#新磁碟與-pending-recovery-操作" aria-label="Permalink to &quot;新磁碟與 pending recovery 操作&quot;">​</a></h3><p>舊預設 <code>build/wuwaos.img</code> 若是 WUFS0001，會保留唯讀。建立並啟動一顆新 WUFS0002：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wsl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d Ubuntu </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bash </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lc </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;cd /mnt/c/programing/WUWAOS &amp;&amp; make run DISK_IMAGE=build/wuwaos-v2.img SWAP_IMAGE=build/wuwaos-v2-swap.img&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>portable Windows 環境可執行 <code>.\\Start-WUWAOS.cmd shell</code> 進入 bundled Bash，再執行相同的 <code>make run DISK_IMAGE=... SWAP_IMAGE=...</code>。若 host formatter 因 pending journal 拒絕更新，先直接呼叫 QEMU，跳過 <code>disk-image</code> target；以下例子使用上述兩個檔名：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qemu-system-riscv64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -machine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> virt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -smp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 128M</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nographic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -bios</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -kernel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/kernel.elf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> virtio-mmio.force-legacy=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -drive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file=build/wuwaos-v2.img,if=none,format=raw,id=fs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> virtio-blk-device,drive=fs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -drive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file=build/wuwaos-v2-swap.img,if=none,format=raw,id=swap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> virtio-blk-device,drive=swap</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>若要復原 <code>make run-disk</code> 的預設映像，在專案目錄先用 <code>make</code> 建置 <code>build/kernel.elf</code>。再執行上述直接開機指令，把 <code>file=build/wuwaos-v2.img</code> 換成 <code>file=build/wuwaos-cli.img</code>，並省略兩個 swap 參數。磁碟開機載入器會拒絕有待重播紀錄的映像，因此復原時要由 QEMU 直接載入核心。</p><p>核心掛載時先重播有效的已提交交易，再清除 header。退出 QEMU 後，就能以原本的指令重新啟動該映像。若 journal header 非零但無效，核心會拒絕掛載，應保留映像供檢查。</p><h2 id="驗收紀錄" tabindex="-1">驗收紀錄 <a class="header-anchor" href="#驗收紀錄" aria-label="Permalink to &quot;驗收紀錄&quot;">​</a></h2><p>2026-11-06，WSL Ubuntu／Clang／QEMU virt 單 hart、128 MiB。未加入測試程式碼；下列映像與 serial log 均在 <code>build/wufs-*-scratch.*</code>／<code>build/qemu-*.log</code>，未使用正常 WUFS 或 swap 磁碟。</p><ul><li><code>make -j2 all build/kernel-disk.elf</code> 通過 <code>-Wall -Wextra -Werror</code> 及既有 linker budget。新 V2 host image 為 16 MiB，magic/欄位與 journal LBA 範圍符合表格；主機 formatter 能在既有 V2 上驗證並原子更新。</li><li>正常 QEMU 建立 <code>/txn</code>、整檔寫入 <code>hello</code>、touch、copy、cat、remove、remove-tree；<code>echo &gt;</code>／<code>&gt;&gt;</code> 的 FD create/truncate/append 寫入成功，重啟後 <code>cat /txn/a</code> 仍讀到 <code>hello</code>。<code>fan /home/user/note</code> 輸入 <code>fan safe save</code>，Ctrl+O 顯示 14 bytes Saved，Ctrl+X 離開；重啟再開 fan 顯示同樣內容，cat 亦讀回。</li><li>滿盤 scratch：host 安裝 409600-byte source、<code>KEEP-OLD</code> destination 及 29 個 528384-byte filler，剩 303 sectors。QEMU <code>cp /home/user/source /home/user/dest</code> 回 <code>-28</code>；隨後 cat 仍是 <code>KEEP-OLD</code>。關機後 host formatter 完整驗證同一磁碟成功，journal header 為零且 free sectors 仍為 303。</li><li>QEMU blkdebug 在 journal payload LBA 11 注入單次 EIO。對既有 destination 的整檔 write 回 <code>-5</code>；header 保持全零，host metadata 驗證成功，解析目的檔仍是原內容 <code>NEW</code>。紀錄：<code>build/qemu-precommit.log</code>。</li><li>QEMU blkdebug 在 home inode sector LBA 1178 注入 EIO，讓 LBA 1163 inode bitmap 已 checkpoint、後續 home sector 失敗。操作回 <code>-5</code>，磁碟保留有效 <code>WUJNL002</code>。普通 QEMU 重啟印出 <code>Replayed committed WUFS journal</code>，<code>ls /</code> 找到 <code>/partial/</code>，且 host 驗證/更新成功。紀錄：<code>build/qemu-checkpoint.log</code>、<code>build/qemu-replay.log</code>。</li><li>另在 home inode bitmap LBA 1163 注入 EIO，單筆 mkdir 回錯，重啟 replay 後 <code>/fault/</code> 存在。QEMU 的 blkdebug I/O error 測試是 checkpoint failure/restart recovery，不代表真實突然斷電測試。故障情境使用 <code>werror=report,rerror=report</code> 避免 QEMU 預設暫停 VM。</li><li>全零 scratch 首次 boot 顯示 <code>Initializing blank disk as WUFS0002</code>，目錄可讀；關機後 host formatter 通過 metadata validation。最後一 byte 非零的 unknown scratch 顯示 <code>Unknown or damaged filesystem ... refusing format</code>，SHA-256 前後皆 <code>0cc9ac108468572e9a13a9e41c02fe8d76efa9708f7f8a86a3b103a7dba21a64</code>。</li><li>無效非零 journal header scratch 的 kernel log 為 <code>Invalid or unrecoverable journal</code>，host formatter 明確拒絕；映像 SHA-256 前後皆 <code>0109f2ac1eb3487dd801cee04d477ede114480a99f1ee679189b70bd250da5bb</code>。將 data_start 改錯的 layout scratch 被 kernel、host 都拒絕且 hash不變；把 <code>/home/user/dest</code> inode direct pointer 改為 journal sector 1 的 scratch 被 kernel metadata validator、host validator 都拒絕且 hash 不變。紀錄：<code>build/qemu-invalid-journal.log</code>、<code>build/qemu-invalid-layout.log</code>、<code>build/qemu-invalid-pointer.log</code>。</li><li>原 WUFS0001 磁碟的獨立 scratch copy 可唯讀掛載及 <code>ls /</code>；寫入回 <code>-30</code>。host tool 執行後 hash 不變。此 scratch copy SHA-256 與原映像皆為 <code>6ba61b2e9e6c5af4931dd39d338619bf66bf25c5639bb916adc59b6b62fd4989</code>；原始 <code>build/wuwaos.img</code> 未供 QEMU 掛載、未修改。QEMU 使用獨立 scratch swap。</li><li>原始 swap <code>build/wuwaos-swap.img</code> 在驗收前後均為 SHA-256 <code>f6ddb73f54cf434916200d752a0596b14da7d6534fe0f8cf454e6b1c02078355</code>；QEMU 使用獨立 scratch swap。</li></ul><h2 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h2><ul><li>Flush 信任裝置宣告的 VirtIO FLUSH 語意；QEMU 注入的 sector write errors 不等於電源中斷或實體裝置快取測試。資料區整體 checksum、磁碟影像本身的損毀救援、journal 自動修補均未實作。</li><li>1152-sector capacity 是 hard bound；大量 <code>remove_tree</code>／copy 可能回 <code>-28</code>，呼叫者可用較小操作拆分，但每次 API 仍保持單筆 transaction。</li><li>Legacy V1 在 write-protect 協定中檢查後唯讀，不升級；不支援 FLUSH 的 V2 只在 journal clean 時唯讀可用。</li><li>DMA request timeout 仍停住核心；不做 device reset/retry。</li></ul><h2 id="參考" tabindex="-1">參考 <a class="header-anchor" href="#參考" aria-label="Permalink to &quot;參考&quot;">​</a></h2><ul><li>使用者課程筆記：<code>notes/chapter 14 File-System Implementation.md</code> §14.7 Recovery；<code>notes/ch12 I_O Systems.md</code> I/O、DMA 與 buffering 章節。教科書說明 journaling/redo 概念，WUWAOS 實際採本規格所列完整 sector redo。</li><li><a href="https://docs.oasis-open.org/virtio/virtio/v1.2/virtio-v1.2.html#x1-3860005.2.6.2" target="_blank" rel="noreferrer">OASIS VirtIO 1.2, Block Device FLUSH</a></li><li><a href="https://www.qemu.org/docs/master/devel/testing/blkdebug.html" target="_blank" rel="noreferrer">QEMU blkdebug error injection</a></li></ul>`,35)])])}const k=a(s,[["render",d]]);export{u as __pageData,k as default};
